-- V2.1 20-slot catalog
create table if not exists public.slot_catalog (id uuid primary key default gen_random_uuid(),slot_key text unique not null,name text not null,provider_source text not null,license_note text not null,status text not null default 'candidate' check(status in ('candidate','integrated','disabled')),demo_only boolean not null default true);
